'use client';

/**
 * Invite Result Dialog.
 *
 * Displays an invitation or password-reset link generated by the server.
 * The user can copy the link, open it in a new tab, or close the dialog.
 *
 * Extracted from src/components/views/employees-view.tsx (Phase 3).
 */

import { Globe, Copy, ExternalLink, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from '@/components/ui/dialog';
import type { InviteResult } from '../types';

export interface InviteResultDialogProps {
  result: InviteResult | null;
  onOpenChange: (open: boolean) => void;
  onCopy: (text: string) => void;
}

export function InviteResultDialog({ result, onOpenChange, onCopy }: InviteResultDialogProps) {
  return (
    <Dialog open={!!result} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Globe className="size-5 text-teal-600" />
            {result?.mode === 'reset' ? 'Password Reset Link' : 'Invitation Link'}
          </DialogTitle>
          <DialogDescription>{result?.message}</DialogDescription>
        </DialogHeader>
        <div className="space-y-3 py-2">
          <div className="rounded-lg bg-teal-50 dark:bg-teal-950/30 border border-teal-200 dark:border-teal-800 p-3">
            <p className="text-xs font-medium text-teal-700 dark:text-teal-300 mb-1">
              {result?.mode === 'reset' ? 'Reset Link' : 'Activation Link'}
            </p>
            <p className="text-xs font-mono text-teal-900 dark:text-teal-100 break-all">
              {result?.url}
            </p>
          </div>
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              className="flex-1"
              onClick={() => result && onCopy(result.url)}
            >
              <Copy className="size-3.5 mr-1.5" /> Copy Link
            </Button>
            <Button
              variant="outline"
              size="sm"
              className="flex-1"
              onClick={() => result && window.open(result.url, '_blank')}
            >
              <ExternalLink className="size-3.5 mr-1.5" /> Open
            </Button>
          </div>
          <div className="flex items-start gap-2 text-xs text-muted-foreground bg-muted/30 p-3 rounded-lg">
            <AlertCircle className="size-3.5 shrink-0 mt-0.5" />
            <span>
              Share this link with {result?.email}. The link expires in {result?.mode === 'reset' ? '2 hours' : '7 days'}.
              {result?.mode === 'invite' && ' They will set their own password on first login.'}
            </span>
          </div>
        </div>
        <DialogFooter>
          <Button onClick={() => onOpenChange(false)}>Done</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
